```go
package main

import (
	"encoding/json"
	"log"
	"net/http"
	"sync"
)

type Todo struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

type store struct {
	mu    sync.RWMutex
	todos []Todo
}

func (s *store) list(w http.ResponseWriter, r *http.Request) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(s.todos); err != nil {
		log.Printf("encode todos: %v", err)
	}
}

func main() {
	s := &store{todos: []Todo{
		{ID: 1, Title: "buy milk"},
		{ID: 2, Title: "write report", Done: true},
	}}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /todos", s.list)

	log.Println("listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", mux))
}
```

- `"GET /todos"` uses the method patterns added in Go 1.22; other methods on that path get `405 Method Not Allowed` automatically.
- `sync.RWMutex` because handlers run concurrently. Readers can share the lock.
- `json.NewEncoder(w)` writes straight into the response. If encoding fails halfway, the status is already sent, so logging is all we can do.
- Try it with `curl localhost:8080/todos`.

```go
package main

import (
	"encoding/json"
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync"
)

type Todo struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

type store struct {
	mu     sync.RWMutex
	todos  []Todo
	nextID int
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(v); err != nil {
		log.Printf("write json: %v", err)
	}
}

func (s *store) list(w http.ResponseWriter, r *http.Request) {
	s.mu.RLock()
	todos := make([]Todo, len(s.todos))
	copy(todos, s.todos)
	s.mu.RUnlock()
	writeJSON(w, http.StatusOK, todos)
}

func (s *store) get(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.PathValue("id"))
	if err != nil {
		http.Error(w, "invalid id", http.StatusBadRequest)
		return
	}
	s.mu.RLock()
	defer s.mu.RUnlock()
	for _, t := range s.todos {
		if t.ID == id {
			writeJSON(w, http.StatusOK, t)
			return
		}
	}
	http.Error(w, "not found", http.StatusNotFound)
}

func (s *store) create(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Title string `json:"title"`
	}
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		http.Error(w, "invalid JSON body", http.StatusBadRequest)
		return
	}
	in.Title = strings.TrimSpace(in.Title)
	if in.Title == "" {
		http.Error(w, "title is required", http.StatusUnprocessableEntity)
		return
	}

	s.mu.Lock()
	s.nextID++
	t := Todo{ID: s.nextID, Title: in.Title}
	s.todos = append(s.todos, t)
	s.mu.Unlock()

	w.Header().Set("Location", "/todos/"+strconv.Itoa(t.ID))
	writeJSON(w, http.StatusCreated, t)
}

func main() {
	s := &store{
		todos: []Todo{
			{ID: 1, Title: "buy milk"},
			{ID: 2, Title: "write report", Done: true},
		},
		nextID: 2,
	}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /todos", s.list)
	mux.HandleFunc("GET /todos/{id}", s.get)
	mux.HandleFunc("POST /todos", s.create)

	log.Println("listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", mux))
}
```

- `r.PathValue("id")` reads the `{id}` wildcard from the pattern (Go 1.22+), so no third-party router is needed.
- `list` copies the slice under the read lock and encodes outside it, so a slow client can't hold the lock.
- `http.MaxBytesReader` caps the request body at 1 MiB.
- `POST` returns `201 Created` with a `Location` header pointing to the new todo.
- Try it: `curl -X POST localhost:8080/todos -d '{"title":"call mom"}'`, then `curl localhost:8080/todos/3`.

